export const ArticleListDocument = gql`
    query ArticleList($filter: ArticleFilter, $cursor: String, $take: Int, $skip: Int, $order: SortOrder, $sort: ArticleSort) {
  articles(
    filter: $filter
    cursorId: $cursor
    take: $take
    skip: $skip
    order: $order
    sort: $sort
  ) {
    nodes {
      ...ArticleWithoutBlocks
      latest {
        id
        createdAt
        publishedAt
        title
        authors {
          id
          name
        }
      }
    }
    pageInfo {
      startCursor
      endCursor
      hasNextPage
      hasPreviousPage
    }
    totalCount
  }
}
    ${ArticleWithoutBlocksFragmentDoc}`;

